          const splitText = docPdf.splitTextToSize(textData, width - (margin * 2));
          docPdf.text(splitText, margin, currentY); currentY += 20;

          if (docType === 'matricula') {
              docPdf.text(`Encontra-se regularmente MATRICULADO(A) no curso de ${courseData.nome || 'Teologia Livre'}, modalidade EAD.`, margin, currentY);
              currentY += 10; docPdf.text(`Situação Acadêmica: ${opStudent.status?.toUpperCase()}.`, margin, currentY);
          } else if (docType === 'conclusao') {
              docPdf.text(`Concluiu com êxito o curso de ${courseData.nome || 'Teologia'}, cumprindo a carga horária total exigida e obtendo a aprovação necessária.`, margin, currentY);
              currentY += 10; docPdf.text(`Data de Conclusão: ${new Date().toLocaleDateString('pt-BR')}`, margin, currentY);
          } else if (docType === 'historico') {
              currentY += 10; docPdf.setFont("helvetica", "bold"); docPdf.text(`Curso: ${courseData.nome || '---'}`, margin, currentY); currentY += 10;
              const tableBody = modulesData.map((m: any) => [ m.title || "Módulo", "20h", "100%", "10.0", "APROVADO" ]);
              autoTable(docPdf, { startY: currentY, head: [['Disciplina / Módulo', 'C.H.', 'Freq.', 'Nota', 'Situação']], body: tableBody, theme: 'grid', headStyles: { fillColor: [40, 40, 40] }, styles: { fontSize: 9, font: "helvetica" }, margin: { left: margin, right: margin } });
              currentY = (docPdf as any).lastAutoTable.finalY + 20;
          }

          currentY = Math.max(currentY, height - 90);
          docPdf.text(`São Paulo, ${new Date().toLocaleDateString('pt-BR', {day:'numeric', month:'long', year:'numeric'})}.`, width - margin, currentY, { align: "right" });

          // Signatures
          const sigY = height - 60;
          docPdf.line(margin + 10, sigY, margin + 70, sigY); docPdf.setFontSize(8); docPdf.text("Diretor Executivo", margin + 40, sigY + 5, { align: "center" });
          docPdf.line(width - margin - 70, sigY, width - margin - 10, sigY); docPdf.text("Secretaria Geral", width - margin - 40, sigY + 5, { align: "center" });

          // Footer
          const footerY = height - 25;
          docPdf.setDrawColor(200); docPdf.line(margin, footerY, width - margin, footerY);
