  const [currentFolderId, setCurrentFolderId] = useState<string>('root');
  const [folderPath, setFolderPath] = useState<{id: string, name: string}[]>([{id: 'root', name: 'Arquivos'}]);
  const [moveModalOpen, setMoveModalOpen] = useState(false);
  const [fileToMove, setFileToMove] = useState<any>(null);
  const [moveTargetFolderId, setMoveTargetFolderId] = useState('root');
  const [attachMode, setAttachMode] = useState(false); // Para anexar arquivos da secretaria no chat

  // Refs
  const fileInputRef = useRef<HTMLInputElement>(null);
  const chatFileInputRef = useRef<HTMLInputElement>(null);
  const chatEndRef = useRef<HTMLDivElement>(null);

  // Operacional
  const [opStudent, setOpStudent] = useState<any>(null);
  const [isGeneratingPdf, setIsGeneratingPdf] = useState(false);
  const [auditModalOpen, setAuditModalOpen] = useState(false);
  const [editingStudent, setEditingStudent] = useState<any | null>(null);

  useEffect(() => {
    const unsubT = onSnapshot(collection(db, 'tickets'), s => {
        const t = s.docs.map(d => ({ id: d.id, ...d.data() }));
        // Ordenar por prioridade implícita e data
        t.sort((a:any, b:any) => (b.createdAt?.seconds || 0) - (a.createdAt?.seconds || 0));
        setTickets(t);
        if (activeTicket) {
            const updated = t.find((x: any) => x.id === activeTicket.id);
            if (updated) setActiveTicket(updated);
        }
    });

    const unsubF = onSnapshot(collection(db, 'secretaria_arquivos'), s => {
      setFileSystem(s.docs.map(d => ({ id: d.id, ...d.data() })));
    });

    const unsubS = onSnapshot(collection(db, 'users'), s => {
      const allUsers = s.docs.map(d => ({ uid: d.id, ...d.data() }));
      setStudents(allUsers.filter((u: any) => u.role === 'aluno'));
    });

    return () => { unsubT(); unsubF(); unsubS(); };
  }, [user.uid, activeTicket?.id]);

  useEffect(() => {
    if (!activeTicket) { setMessages([]); return; }
    const q = query(collection(db, 'tickets', activeTicket.id, 'messages'), orderBy('createdAt', 'asc'));
    return onSnapshot(q, (snap) => {
      setMessages(snap.docs.map(d => ({ id: d.id, ...d.data() })));
      setTimeout(() => chatEndRef.current?.scrollIntoView({ behavior: 'smooth' }), 100);
    });
  }, [activeTicket]);

  // --- PAGINATION LOGIC ---
  const filteredTickets = useMemo(() => {
      return tickets.filter(t => {
          const matchesStatus = ticketFilter === 'todos' 
              ? (t.status !== 'Arquivado') 
              : ticketFilter === 'arquivado' ? t.status === 'Arquivado' : t.status.toLowerCase() === ticketFilter;
          const matchesSearch = t.protocolo?.toLowerCase().includes(ticketSearchTerm.toLowerCase()) || 
                                t.user?.toLowerCase().includes(ticketSearchTerm.toLowerCase()) ||
                                t.studentId?.toLowerCase().includes(ticketSearchTerm.toLowerCase());
          return matchesStatus && matchesSearch;
      });
  }, [tickets, ticketFilter, ticketSearchTerm]);

  const paginatedTickets = useMemo(() => {
      const start = (currentPage - 1) * itemsPerPage;
      return filteredTickets.slice(start, start + itemsPerPage);
  }, [filteredTickets, currentPage, itemsPerPage]);

  const totalPages = Math.ceil(filteredTickets.length / itemsPerPage);

  // --- MANUAL TICKET ---
  const handleCreateManualTicket = async () => {
      if (!manualTicketForm.studentId || !manualTicketForm.description) return;
      const student = students.find(s => s.uid === manualTicketForm.studentId);

      const docRef = await addDoc(collection(db, 'tickets'), {
          user: student?.displayName || 'Aluno Manual',
          senderId: student?.uid,
          protocolo: Math.random().toString(36).substr(2, 9).toUpperCase(),
          channel: manualTicketForm.channel,
          lastMessage: manualTicketForm.description, // Initial description
          status: 'Pendente',
          priority: 'Normal', // Default
          createdAt: serverTimestamp(),
          updatedAt: serverTimestamp(),
          manual: true
      });

      // Add initial message as description
      await addDoc(collection(db, 'tickets', docRef.id, 'messages'), {
          text: `[Abertura Manual - ${manualTicketForm.channel.toUpperCase()}]: ${manualTicketForm.description}`,
          sender: 'Secretaria',
          createdAt: serverTimestamp()
      });

      setShowManualTicketModal(false);
      setManualTicketForm({ studentId: '', channel: 'whatsapp', description: '' });
      alert("Protocolo aberto com sucesso!");
  };

  // --- CHAT ACTIONS ---
  const sendMessage = async () => {
    if (!chatMessage.trim() || !activeTicket) return;
    await addDoc(collection(db, 'tickets', activeTicket.id, 'messages'), { text: chatMessage, sender: 'Secretaria', createdAt: serverTimestamp() });
    await updateDoc(doc(db, 'tickets', activeTicket.id), { lastMessage: chatMessage, updatedAt: serverTimestamp() });
    setChatMessage('');
  };

  const handleDynamicButton = async () => {
      if (!activeTicket) return;

      if (activeTicket.status === 'Pendente') {
          // ASSUMIR
          await updateDoc(doc(db, 'tickets', activeTicket.id), { 
              status: 'Em Atendimento', 
              attendantId: user.uid,
              attendantName: user.displayName,
              updatedAt: serverTimestamp() 
          });
          // Send system msg
          await addDoc(collection(db, 'tickets', activeTicket.id, 'messages'), {
              text: `O atendente ${user.displayName} assumiu este chamado.`,
              sender: 'Sistema',
              isBot: true,
              createdAt: serverTimestamp()
          });
      } else if (activeTicket.status === 'Em Atendimento') {
          // FINALIZAR
          if(!confirm("Tem certeza que deseja finalizar este atendimento? O aluno receberá a pesquisa de satisfação.")) return;
          await updateDoc(doc(db, 'tickets', activeTicket.id), { 
              status: 'Resolvido', 
              updatedAt: serverTimestamp() 
          });
          await addDoc(collection(db, 'tickets', activeTicket.id, 'messages'), {
              text: `Atendimento finalizado por ${user.displayName}.`,
              sender: 'Sistema',
              isBot: true,
              createdAt: serverTimestamp()
          });
      } else if (activeTicket.status === 'Resolvido' || activeTicket.status === 'Finalizado') {
          // ARQUIVAR
          await updateDoc(doc(db, 'tickets', activeTicket.id), { 
              status: 'Arquivado', 
              updatedAt: serverTimestamp() 
          });
          setActiveTicket(null); // Close chat
          setActiveTab('atendimento'); // Go back to list
      }
  };

  const handleDeleteTicket = async (id: string) => {
      if(!confirm("ATENÇÃO: Isso excluirá permanentemente o histórico deste protocolo. Continuar?")) return;
      await deleteDoc(doc(db, 'tickets', id));
  };

  const handleArchiveTicket = async (id: string) => {
      await updateDoc(doc(db, 'tickets', id), { status: 'Arquivado' });
  };

  // --- PDF GENERATOR ---
  const generateLegalPDF = async (docType: 'matricula' | 'conclusao' | 'transferencia' | 'historico') => {
      if (!opStudent) { alert("Selecione um aluno primeiro."); return; }
      setIsGeneratingPdf(true);
      try {
          const code = generateVerificationCode();
          const docTitle = docType === 'matricula' ? 'DECLARAÇÃO DE MATRÍCULA' : 
                           docType === 'conclusao' ? 'CERTIFICADO DE CONCLUSÃO' : 
                           docType === 'historico' ? 'HISTÓRICO ESCOLAR' : 'GUIA DE TRANSFERÊNCIA';

          let courseData: any = {};
          let modulesData: any[] = [];

          if (opStudent.cursoInicial) {
              const cSnap = await getDoc(doc(db, 'cursos', opStudent.cursoInicial));
              if (cSnap.exists()) courseData = cSnap.data();

              const mQuery = query(collection(db, 'modulos'), where('courseId', '==', opStudent.cursoInicial));
              const mSnap = await getDocs(mQuery);
              modulesData = mSnap.docs.map(d => d.data()).sort((a: any, b: any) => (a.order || 0) - (b.order || 0));
          }

          const validationUrl = `${window.location.origin}?code=${code}`;
          const qrCodeDataUrl = await QRCode.toDataURL(validationUrl, { margin: 1, width: 100 });

          // PDF Setup
          const docPdf = new jsPDF({ orientation: docType === 'conclusao' ? 'landscape' : 'portrait', unit: 'mm', format: 'a4' });
          const width = docPdf.internal.pageSize.getWidth();
          const height = docPdf.internal.pageSize.getHeight();

          // --- PAGE 1: MAIN DOCUMENT ---

          // Ornamental Border (Double Line Gold/Black)
          docPdf.setDrawColor(218, 165, 32); // Gold
          docPdf.setLineWidth(2);
          docPdf.rect(5, 5, width - 10, height - 10); // Outer
          docPdf.setDrawColor(0); // Black
          docPdf.setLineWidth(0.5);
          docPdf.rect(8, 8, width - 16, height - 16); // Inner

          // Logo / Header Area
          docPdf.setFont("times", "bold");
          docPdf.setFontSize(28);
          docPdf.setTextColor(20, 20, 50);
          docPdf.text("ESCOLA BÍBLICA EAD", width / 2, 35, { align: "center" });

          docPdf.setFontSize(10);
          docPdf.setFont("helvetica", "normal");
          docPdf.setTextColor(100);
          docPdf.text("Credenciamento MEC/CNE nº 999.999 | Portaria Nº 1004 de 17/08/2017", width / 2, 42, { align: "center" });

          // Decorative Line
          docPdf.setDrawColor(200);
          docPdf.line(40, 48, width - 40, 48);

          // Title
          docPdf.setFont("times", "bold");
          docPdf.setFontSize(32);
          docPdf.setTextColor(0);
          docPdf.text(docTitle, width / 2, 70, { align: "center" });

          // Content
          docPdf.setFont("times", "normal");
          docPdf.setFontSize(14);
          const margin = 30;
          let currentY = 90;

          const textData = `Certificamos para os devidos fins que o(a) aluno(a) ${opStudent.displayName?.toUpperCase()}, portador(a) do CPF nº ${opStudent.cpf || '---'}, matrícula nº ${opStudent.academicId || '---'}.`;
          const splitText = docPdf.splitTextToSize(textData, width - (margin * 2));
          docPdf.text(splitText, width/2, currentY, { align: "center" });
          currentY += 20 + (splitText.length * 7);

          if (docType === 'matricula') {
              docPdf.text(`Encontra-se regularmente MATRICULADO(A) no curso de ${courseData.nome || 'Teologia Livre'}, modalidade EAD.`, width/2, currentY, { align: "center" });
              currentY += 10;
              docPdf.text(`Situação Acadêmica: ${opStudent.status?.toUpperCase()}.`, width/2, currentY, { align: "center" });
          } else if (docType === 'conclusao') {
              const concText = `Concluiu com êxito o curso de ${courseData.nome || 'Teologia'}, cumprindo a carga horária total exigida e obtendo a aprovação necessária para a outorga deste título.`;
              const splitConc = docPdf.splitTextToSize(concText, width - (margin * 2));
              docPdf.text(splitConc, width/2, currentY, { align: "center" });
              currentY += 20;
              docPdf.text(`Data de Conclusão: ${new Date().toLocaleDateString('pt-BR')}`, width/2, currentY, { align: "center" });
          } else if (docType === 'historico') {
              docPdf.text(`Solicitou seu histórico escolar referente ao curso de ${courseData.nome || '---'}.`, width/2, currentY, { align: "center" });
          } else {
              docPdf.text(`Solicitou transferência para outra instituição de ensino.`, width/2, currentY, { align: "center" });
          }

          // Date and Place
          currentY = height - 80;
          const dateStr = `São Paulo, ${new Date().toLocaleDateString('pt-BR', {day:'numeric', month:'long', year:'numeric'})}.`;
          docPdf.text(dateStr, width - margin, currentY, { align: "right" });

          // Digital Authentication Area (Replaces Signatures)
          const authY = height - 50;

          // Only Certificate gets the QR on the signature spot
          if (docType === 'conclusao') {
             // Center QR
             docPdf.addImage(qrCodeDataUrl, 'PNG', (width/2) - 15, authY, 30, 30);
             docPdf.setFontSize(8);
             docPdf.text("VALIDAÇÃO DIGITAL", width/2, authY + 32, { align: "center" });
             docPdf.text(`Hash: ${code}`, width/2, authY + 36, { align: "center" });
          } else {
             // Other docs just get a text stamp
             docPdf.setDrawColor(0);
             docPdf.rect(width/2 - 40, authY, 80, 25);
             docPdf.setFontSize(10);
             docPdf.setFont("helvetica", "bold");
             docPdf.text("ASSINADO DIGITALMENTE", width/2, authY + 10, { align: "center" });
             docPdf.setFontSize(8);
             docPdf.setFont("helvetica", "normal");
             docPdf.text("Secretaria Geral EB-EAD", width/2, authY + 18, { align: "center" });
          }

          // --- PAGE 2: BACK (Only for Certificate) ---
          if (docType === 'conclusao') {
              docPdf.addPage();

              // Simple Border Page 2
              docPdf.setDrawColor(0);
              docPdf.setLineWidth(0.5);
              docPdf.rect(10, 10, width - 20, height - 20);

              docPdf.setFont("helvetica", "bold");
              docPdf.setFontSize(14);
              docPdf.text("VERSO - HISTÓRICO E DETALHES", width / 2, 20, { align: "center" });

              let y2 = 40;
              docPdf.setFontSize(10);
              docPdf.text(`Curso: ${courseData.nome || '---'}`, 20, y2);
              docPdf.text(`Carga Horária Total: ${modulesData.length * 20} horas`, 20, y2 + 6);
              docPdf.text(`Aluno: ${opStudent.displayName}`, 20, y2 + 12);

              y2 += 25;

              // Modules Table
              const tableBody = modulesData.map((m: any) => [
                  m.title || "Módulo",
                  "20h",
                  "10.0", // Simulado
                  "APROVADO"
              ]);

              autoTable(docPdf, {
                  startY: y2,
                  head: [['Disciplina / Módulo', 'C.H.', 'Nota Final', 'Situação']],
                  body: tableBody,
                  theme: 'grid',
                  headStyles: { fillColor: [220, 220, 220], textColor: 0, fontSize: 9 },
                  styles: { fontSize: 8, font: "helvetica" },
                  margin: { left: 20, right: 20 }
              });

              // QR Code for Validation at Bottom of Page 2
              const finalY = (docPdf as any).lastAutoTable.finalY + 20;
              docPdf.text("Verificação de Autenticidade:", 20, finalY);
              docPdf.addImage(qrCodeDataUrl, 'PNG', 20, finalY + 5, 25, 25);
              docPdf.setFontSize(8);
              docPdf.text(code, 50, finalY + 15);
              docPdf.text("Acesse o portal para validar este documento.", 50, finalY + 20);
          }

          const pdfBase64 = docPdf.output('datauristring');
          const pdfBlob = docPdf.output('blob');

          // Save to Files
          await addDoc(collection(db, 'secretaria_arquivos'), {
              name: `${docTitle} - ${opStudent.displayName}.pdf`, type: 'file', mimeType: 'application/pdf', url: pdfBase64,
              parentId: 'root', createdAt: serverTimestamp(), createdBy: user.uid, studentId: opStudent.uid, docType: docType,
              docData: { code, title: docTitle, date: new Date().toISOString(), student: { displayName: opStudent.displayName, cpf: opStudent.cpf, academicId: opStudent.academicId }, courseData, modulesData }
          });

          const blobUrl = URL.createObjectURL(pdfBlob); window.open(blobUrl, '_blank');
          alert("Documento gerado e arquivado com sucesso!");
      } catch (e: any) { console.error("Erro PDF:", e); alert("Erro ao gerar: " + e.message); } finally { setIsGeneratingPdf(false); }
  };

  // --- ATTACHMENT FROM LOCAL ---
  const handleLocalAttachment = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if(!file || !activeTicket) return;
      const reader = new FileReader();
      reader.onload = async (ev) => {
          if(ev.target?.result) {
              await addDoc(collection(db, 'tickets', activeTicket.id, 'messages'), { text: `Anexo Local: ${file.name}`, attachmentUrl: ev.target.result as string, sender: 'Secretaria', createdAt: serverTimestamp() });
          }
      };
      reader.readAsDataURL(file);
  };

  // --- ATTACHMENT FROM FILESYSTEM ---
  const handleSystemAttachment = async () => {
      // Abre modal de arquivos, seleciona e anexa (Simulado aqui por brevidade, apenas abre a aba)
      setActiveTab('arquivos');
      setAttachMode(true);
      // Logic inside Files tab handles the "Select"
  };

  const handleAttachFromFiles = async (file: any) => {
      if (!activeTicket) return;
      await addDoc(collection(db, 'tickets', activeTicket.id, 'messages'), {
          text: `Anexo do Sistema: ${file.name}`,
          attachmentUrl: file.url,
          sender: 'Secretaria',
          createdAt: serverTimestamp()
      });
      setAttachMode(false);
      setActiveTab('chat');
  };

  return (
    <div className="space-y-4 h-full flex flex-col pb-6">
      <header className="flex flex-col md:flex-row justify-between items-center bg-slate-900 p-4 text-white gap-4 rounded-xl shadow-lg print:hidden shrink-0">
        <div className="flex items-center gap-3">
           <div className="p-2 bg-indigo-600 rounded-lg shadow-lg"><Archive size={20}/></div>
           <div><h1 className="text-lg font-black uppercase italic tracking-tighter leading-none">Secretaria Digital</h1><p className="text-[9px] text-indigo-400 font-bold uppercase tracking-widest mt-0.5 italic">Gestão & Atendimento</p></div>
        </div>
        <div className="flex bg-slate-800 p-1 rounded-lg shadow-inner border border-white/5">
           {(['atendimento', 'chat', 'arquivos', 'operacional'] as any).map((t:any) => (
             <button key={t} onClick={() => { setActiveTab(t); setOpSubView('main'); if(t !== 'chat') setActiveTicket(null); }} className={`px-4 py-2 text-[9px] font-black uppercase italic transition-all rounded-lg ${activeTab === t ? 'bg-white text-slate-900' : 'text-slate-400 hover:text-white'}`}>{t}</button>
           ))}
        </div>
      </header>

      <main className="flex-1 overflow-hidden flex flex-col relative">
         {/* TAB: ATENDIMENTO (TICKETS) */}
         {activeTab === 'atendimento' && (
             <div className="flex-1 bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden flex flex-col">
                <div className="p-4 border-b border-slate-100 flex flex-col md:flex-row items-center justify-between bg-slate-50 gap-4">
                    <div className="flex gap-2 overflow-x-auto w-full md:w-auto">
                       {['todos', 'pendente', 'ativo', 'finalizado', 'arquivado'].map((f:any) => (
                           <button key={f} onClick={() => { setTicketFilter(f); setCurrentPage(1); }} className={`px-3 py-1.5 rounded-lg text-[10px] font-black uppercase transition-all whitespace-nowrap ${ticketFilter === f ? 'bg-indigo-600 text-white' : 'bg-white border border-slate-200 text-slate-500 hover:bg-slate-100'}`}>{f}</button>
                       ))}
                    </div>
                    <div className="flex gap-2 w-full md:w-auto">
                        <div className="relative flex-1 md:flex-none">
                            <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400"/>
                            <input value={ticketSearchTerm} onChange={e => setTicketSearchTerm(e.target.value)} placeholder="Buscar protocolo, nome, matrícula..." className="pl-9 pr-4 py-2 rounded-xl border border-slate-200 text-xs font-bold w-full md:w-64 outline-none focus:ring-1 focus:ring-indigo-600" />
                        </div>
                        <button onClick={() => setShowManualTicketModal(true)} className="px-4 py-2 bg-slate-900 text-white rounded-xl text-[10px] font-black uppercase shadow-lg hover:bg-indigo-600 transition-all flex items-center gap-2 whitespace-nowrap"><Plus size={14}/> Novo Manual</button>
                    </div>
                </div>
                <div className="flex-1 overflow-y-auto p-0">
                    <table className="w-full text-left border-collapse">
                        <thead className="bg-slate-50 sticky top-0 z-10 text-[9px] font-black uppercase text-slate-400 border-b border-slate-200 tracking-widest">
                            <tr>
                                <th className="px-6 py-4">Protocolo</th>
                                <th className="px-6 py-4">Aluno / Matrícula</th>
                                <th className="px-6 py-4">Descrição do Problema</th>
                                <th className="px-6 py-4">Tempo Espera</th>
                                <th className="px-6 py-4">Status / Prioridade</th>
                                <th className="px-6 py-4 text-right">Ações de Gestão</th>
                            </tr>
                        </thead>
                        <tbody className="text-xs divide-y divide-slate-50">
                            {paginatedTickets.map(t => (
                                <tr key={t.id} className="hover:bg-slate-50/80 transition-colors group">
                                    <td className="px-6 py-4 font-mono font-bold text-indigo-600">#{t.protocolo}</td>
                                    <td className="px-6 py-4">
                                        <div className="flex flex-col">
                                            <span className="font-bold text-slate-900">{t.user}</span>
                                            <span className="text-[9px] text-slate-400 italic">ID: {t.senderId?.substr(0,8)}</span>
                                        </div>
                                    </td>
                                    <td className="px-6 py-4 max-w-xs truncate text-slate-600 font-medium">{t.lastMessage}</td>
                                    <td className="px-6 py-4 font-mono text-[10px]">{formatTimeWait(t.createdAt?.seconds)}</td>
                                    <td className="px-6 py-4">
                                        <span className={`px-3 py-1 rounded-full text-[8px] font-black uppercase border ${
                                            t.status === 'Pendente' ? 'bg-amber-50 text-amber-600 border-amber-200' :
                                            t.status === 'Resolvido' || t.status === 'Finalizado' ? 'bg-emerald-50 text-emerald-600 border-emerald-200' :
                                            t.status === 'Arquivado' ? 'bg-slate-100 text-slate-500 border-slate-200' :
                                            'bg-indigo-50 text-indigo-600 border-indigo-200'
                                        }`}>{t.status}</span>
                                    </td>
                                    <td className="px-6 py-4 text-right">
                                        <div className="flex justify-end gap-2">
                                            <button onClick={() => setViewTicketModal(t)} className="p-2 bg-white border border-slate-200 text-slate-400 rounded-lg hover:text-indigo-600 hover:border-indigo-200 transition-all" title="Ver Card Completo"><Eye size={14}/></button>
                                            <button onClick={() => { setActiveTicket(t); setActiveTab('chat'); }} className="p-2 bg-indigo-50 text-indigo-600 border border-indigo-100 rounded-lg hover:bg-indigo-600 hover:text-white transition-all" title="Ir para Chat"><ArrowRightLeft size={14}/></button>
                                            {t.status !== 'Arquivado' && <button onClick={() => handleArchiveTicket(t.id)} className="p-2 bg-white border border-slate-200 text-slate-400 rounded-lg hover:text-amber-600 hover:border-amber-200 transition-all" title="Arquivar"><Archive size={14}/></button>}
                                            <button onClick={() => handleDeleteTicket(t.id)} className="p-2 bg-white border border-slate-200 text-slate-400 rounded-lg hover:text-rose-600 hover:border-rose-200 transition-all" title="Excluir"><Trash2 size={14}/></button>
                                        </div>
                                    </td>
                                </tr>
                            ))}
                            {paginatedTickets.length === 0 && <tr><td colSpan={6} className="p-10 text-center text-slate-400 font-medium italic text-xs">Nenhum registro encontrado.</td></tr>}
                        </tbody>
                    </table>
                </div>
                {/* Pagination Controls */}
                <div className="p-4 border-t border-slate-100 bg-slate-50 flex justify-between items-center text-[10px] font-bold uppercase text-slate-500">
                    <div className="flex items-center gap-2">
                        <span>Exibir:</span>
                        <select value={itemsPerPage} onChange={e => setItemsPerPage(Number(e.target.value))} className="bg-white border border-slate-200 rounded p-1">
                            <option value={10}>10</option>
                            <option value={20}>20</option>
                            <option value={50}>50</option>
                        </select>
                        <span>por página</span>
                    </div>
                    <div className="flex items-center gap-2">
                        <button disabled={currentPage === 1} onClick={() => setCurrentPage(p => p - 1)} className="px-3 py-1 bg-white border rounded disabled:opacity-50 hover:bg-slate-100"><ChevronLeft size={12}/></button>
                        <span>Pág {currentPage} de {totalPages || 1}</span>
                        <button disabled={currentPage === totalPages || totalPages === 0} onClick={() => setCurrentPage(p => p + 1)} className="px-3 py-1 bg-white border rounded disabled:opacity-50 hover:bg-slate-100"><ChevronRight size={12}/></button>
