interface SecretariatViewProps { user: User; }
type SecretariatTab = 'atendimento' | 'chat' | 'arquivos' | 'operacional';
type OperationalSubView = 'main' | 'declaracao' | 'certificado' | 'historico' | 'transferencia' | 'validacao';

// --- HELPERS ---
const generateVerificationCode = () => {
  return `${new Date().getFullYear()}.${Math.random().toString(36).substr(2, 4).toUpperCase()}.${Math.random().toString(36).substr(2, 4).toUpperCase()}`;
};

const formatTimeWait = (seconds: number) => {
    if (!seconds) return '0min';
    const now = Date.now() / 1000;
    const diff = now - seconds;
    if (diff < 60) return 'Agora';
    if (diff < 3600) return `${Math.floor(diff / 60)}min`;
    if (diff < 86400) return `${Math.floor(diff / 3600)}h`;
    return `${Math.floor(diff / 86400)}d`;
};

const viewFile = (file: any) => {
  if (!file || !file.url) return;
  if (file.mimeType === 'application/pdf' || file.name?.endsWith('.pdf')) {
      const newWindow = window.open();
      if (newWindow) {
          if (file.url.startsWith('data:')) {
             newWindow.document.write(`<iframe width='100%' height='100%' src='${file.url}'></iframe>`);
             newWindow.document.title = file.name;
          } else {
             newWindow.location.href = file.url;
          }
      } else { alert("Pop-up bloqueado."); }
      return;
  }
  window.open(file.url, '_blank');
};

const viewAttachment = (url: string) => {
    if (!url) return;
    if (url.startsWith('http')) { window.open(url, '_blank'); return; }
    if (url.startsWith('data:')) {
        const win = window.open();
        if (win) {
            win.document.write(`<iframe src="${url}" frameborder="0" style="border:0; top:0px; left:0px; bottom:0px; right:0px; width:100%; height:100%;" allowfullscreen></iframe>`);
        }
    }
};

const SecretariatView: React.FC<SecretariatViewProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<SecretariatTab>('atendimento');
  const [opSubView, setOpSubView] = useState<OperationalSubView>('main');

  // Data
  const [tickets, setTickets] = useState<any[]>([]);
  const [students, setStudents] = useState<any[]>([]);
  const [fileSystem, setFileSystem] = useState<any[]>([]);

  // Atendimento (Tickets)
  const [ticketSearchTerm, setTicketSearchTerm] = useState('');
  const [ticketFilter, setTicketFilter] = useState<'todos' | 'pendente' | 'ativo' | 'finalizado' | 'arquivado'>('todos');
  const [itemsPerPage, setItemsPerPage] = useState(10);
  const [currentPage, setCurrentPage] = useState(1);
  const [showManualTicketModal, setShowManualTicketModal] = useState(false);
  const [manualTicketForm, setManualTicketForm] = useState({ studentId: '', channel: 'whatsapp', description: '' });
  const [viewTicketModal, setViewTicketModal] = useState<any | null>(null);

  // Chat
  const [activeTicket, setActiveTicket] = useState<any | null>(null);
  const [messages, setMessages] = useState<any[]>([]);
  const [chatMessage, setChatMessage] = useState('');

  // Arquivos
  const [currentFolderId, setCurrentFolderId] = useState<string>('root');
  const [folderPath, setFolderPath] = useState<{id: string, name: string}[]>([{id: 'root', name: 'Arquivos'}]);
  const [moveModalOpen, setMoveModalOpen] = useState(false);
  const [fileToMove, setFileToMove] = useState<any>(null);
  const [moveTargetFolderId, setMoveTargetFolderId] = useState('root');
  const [attachMode, setAttachMode] = useState(false); // Para anexar arquivos da secretaria no chat

  // Refs
  const fileInputRef = useRef<HTMLInputElement>(null);
  const chatFileInputRef = useRef<HTMLInputElement>(null);
  const chatEndRef = useRef<HTMLDivElement>(null);

  // Operacional
  const [opStudent, setOpStudent] = useState<any>(null);
  const [isGeneratingPdf, setIsGeneratingPdf] = useState(false);
  const [auditModalOpen, setAuditModalOpen] = useState(false);
  const [editingStudent, setEditingStudent] = useState<any | null>(null);
  const [schoolConfig, setSchoolConfig] = useState<any>({});

  // Assinaturas
  const [isSignModalOpen, setIsSignModalOpen] = useState(false);
  const [secSignature, setSecSignature] = useState<string | null>(null);
  const [directorSignature, setDirectorSignature] = useState<string | null>(null);

  useEffect(() => {
    const unsubT = onSnapshot(collection(db, 'tickets'), s => {
        const t = s.docs.map(d => ({ id: d.id, ...d.data() }));
        // Ordenar por prioridade implícita e data
        t.sort((a:any, b:any) => (b.createdAt?.seconds || 0) - (a.createdAt?.seconds || 0));
        setTickets(t);
        if (activeTicket) {
            const updated = t.find((x: any) => x.id === activeTicket.id);
            if (updated) setActiveTicket(updated);
        }
    });

    const unsubF = onSnapshot(collection(db, 'secretaria_arquivos'), s => {
      setFileSystem(s.docs.map(d => ({ id: d.id, ...d.data() })));
    });

    const unsubS = onSnapshot(collection(db, 'users'), s => {
      const allUsers = s.docs.map(d => ({ uid: d.id, ...d.data() }));
      setStudents(allUsers.filter((u: any) => u.role === 'aluno'));
    });

    // Config & Signatures
    getDoc(doc(db, 'system_settings', 'main_config')).then(d => { if(d.exists()) setSchoolConfig(d.data().schoolConfig || {}); });
    getDoc(doc(db, 'users', user.uid)).then(d => d.exists() && setSecSignature(d.data().signatureUrl));
    const qDir = query(collection(db, 'users'), where('role', '==', 'diretor'));
    getDocs(qDir).then(s => { if (!s.empty) setDirectorSignature(s.docs[0].data().signatureUrl); });

    return () => { unsubT(); unsubF(); unsubS(); };
  }, [user.uid, activeTicket?.id]);

  // ... (Chat and File Helpers kept same) ...
  useEffect(() => {
    if (!activeTicket) { setMessages([]); return; }
    const q = query(collection(db, 'tickets', activeTicket.id, 'messages'), orderBy('createdAt', 'asc'));
    return onSnapshot(q, (snap) => {
      setMessages(snap.docs.map(d => ({ id: d.id, ...d.data() })));
      setTimeout(() => chatEndRef.current?.scrollIntoView({ behavior: 'smooth' }), 100);
    });
  }, [activeTicket]);

  const getFilesForFolder = (folderId: string) => {
    return fileSystem.filter(f => f.parentId === folderId).sort((a: any, b: any) => {
      if(a.type === b.type) return a.name.localeCompare(b.name);
      return a.type === 'folder' ? -1 : 1;
    });
  };
  const currentItems = useMemo(() => getFilesForFolder(currentFolderId), [fileSystem, currentFolderId]);

  const handleCreateFolder = async () => {
    const name = prompt("Nome da nova pasta:");
    if (!name) return;
    await addDoc(collection(db, 'secretaria_arquivos'), { name, type: 'folder', parentId: currentFolderId, createdAt: serverTimestamp(), createdBy: user.uid });
  };

  const handleUploadFile = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]; if (!file) return;
    const reader = new FileReader();
    reader.onload = async (ev) => {
      if (ev.target?.result) {
        await addDoc(collection(db, 'secretaria_arquivos'), {
          name: file.name, type: 'file', mimeType: file.type, url: ev.target.result, 
          parentId: currentFolderId, size: file.size, createdAt: serverTimestamp(), createdBy: user.uid
        });
      }
    };
    reader.readAsDataURL(file);
  };

  const handleMoveFile = async () => {
      if (!fileToMove) return;
      await updateDoc(doc(db, 'secretaria_arquivos', fileToMove.id), { parentId: moveTargetFolderId, updatedAt: serverTimestamp() });
      setMoveModalOpen(false); setFileToMove(null); alert("Arquivo movido.");
  };

  const sendMessage = async () => {
    if (!chatMessage.trim() || !activeTicket) return;
    await addDoc(collection(db, 'tickets', activeTicket.id, 'messages'), { text: chatMessage, sender: 'Secretaria', createdAt: serverTimestamp() });
    await updateDoc(doc(db, 'tickets', activeTicket.id), { lastMessage: chatMessage, updatedAt: serverTimestamp(), status: 'Em Atendimento', specialistJoined: true });
    setChatMessage('');
  };

  const handleChatFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if(!file || !activeTicket) return;
      const reader = new FileReader();
      reader.onload = async (ev) => {
          if(ev.target?.result) {
              await addDoc(collection(db, 'tickets', activeTicket.id, 'messages'), { text: `Anexo Local: ${file.name}`, attachmentUrl: ev.target.result as string, sender: 'Secretaria', createdAt: serverTimestamp() });
          }
      };
      reader.readAsDataURL(file);
  };

  // --- PDF GENERATOR (Revised) ---
  const generateLegalPDF = async (docType: 'matricula' | 'conclusao' | 'transferencia' | 'historico') => {
      if (!opStudent) { alert("Selecione um aluno primeiro."); return; }
      setIsGeneratingPdf(true);
      try {
          const code = generateVerificationCode();
          const isCertificate = docType === 'conclusao';

          const docTitle = isCertificate ? 'CERTIFICADO DE CONCLUSÃO' : 
                           docType === 'matricula' ? 'DECLARAÇÃO DE MATRÍCULA' : 
                           docType === 'historico' ? 'HISTÓRICO ESCOLAR' : 'GUIA DE TRANSFERÊNCIA';

          let courseData: any = {};
          let modulesData: any[] = [];

          if (opStudent.cursoInicial) {
              const cSnap = await getDoc(doc(db, 'cursos', opStudent.cursoInicial));
              if (cSnap.exists()) courseData = cSnap.data();

              const mQuery = query(collection(db, 'modulos'), where('courseId', '==', opStudent.cursoInicial));
              const mSnap = await getDocs(mQuery);
              modulesData = mSnap.docs.map(d => d.data()).sort((a: any, b: any) => (a.order || 0) - (b.order || 0));
          }

          const validationUrl = `${window.location.origin}?code=${code}`;
          const qrCodeDataUrl = await QRCode.toDataURL(validationUrl, { margin: 1, width: 100 });

          // PDF Setup - Certificate is usually Portrait per prompt (NR 10 example)
          const docPdf = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });
          const width = docPdf.internal.pageSize.getWidth();
          const height = docPdf.internal.pageSize.getHeight();

          // --- PAGE 1 ---

          // Layout Logic
          if (isCertificate) {
              // --- PREMIUM CERTIFICATE DESIGN ---

              // 1. Double Border with Corner Ornaments (Simulated)
              docPdf.setDrawColor(218, 165, 32); // Gold
              docPdf.setLineWidth(2);
              docPdf.rect(10, 10, width - 20, height - 20); // Outer
              docPdf.setDrawColor(0); // Black
              docPdf.setLineWidth(0.5);
              docPdf.rect(13, 13, width - 26, height - 26); // Inner

              // Corner Accents (Simple circles for ornamentation)
              docPdf.setFillColor(218, 165, 32);
              docPdf.circle(10, 10, 2, 'F');
              docPdf.circle(width - 10, 10, 2, 'F');
              docPdf.circle(10, height - 10, 2, 'F');
              docPdf.circle(width - 10, height - 10, 2, 'F');

              let y = 30;

              // 2. Logo (Center Top)
              if (schoolConfig.logoUrl) {
                  const logoW = 30; const logoH = 30;
                  docPdf.addImage(schoolConfig.logoUrl, 'PNG', (width / 2) - (logoW / 2), y, logoW, logoH);
                  y += 35;
              } else {
                  y += 10;
              }

              // 3. Institution Name
              docPdf.setFont("times", "bold");
              docPdf.setFontSize(26);
              docPdf.setTextColor(20, 20, 50);
              docPdf.text(schoolConfig.schoolName || "ESCOLA BÍBLICA EAD", width / 2, y, { align: "center" });

              y += 7;
              docPdf.setFontSize(9);
              docPdf.setFont("helvetica", "normal");
              docPdf.setTextColor(100);
              docPdf.text(`CNPJ: ${schoolConfig.cnpj || '00.000.000/0001-00'} | Portaria MEC nº 1004/2017`, width / 2, y, { align: "center" });

              y += 15;
              docPdf.setFont("times", "bold");
              docPdf.setFontSize(32);
              docPdf.setTextColor(0);
              docPdf.text("CERTIFICADO", width / 2, y, { align: "center" });

              y += 20;
              docPdf.setFont("times", "normal");
              docPdf.setFontSize(14);

              // 4. Main Text Body (Centered & Wrapped)
              const margin = 25;
              const textWidth = width - (margin * 2);

              const certText = `Certificamos que o(a) aluno(a) ${opStudent.displayName?.toUpperCase()}, portador(a) do CPF nº ${opStudent.cpf || '---'}, concluiu com êxito o curso de ${courseData.nome || 'TEOLOGIA'}, cumprindo a carga horária total exigida e obtendo a aprovação necessária para a outorga deste título.`;

              const splitCertText = docPdf.splitTextToSize(certText, textWidth);
              docPdf.text(splitCertText, width / 2, y, { align: "center" });

              y += (splitCertText.length * 8) + 15;

              docPdf.text(`Data de Conclusão: ${new Date().toLocaleDateString('pt-BR')}`, width / 2, y, { align: "center" });
              y += 10;
              docPdf.text(`São Paulo, ${new Date().toLocaleDateString('pt-BR', {day:'numeric', month:'long', year:'numeric'})}.`, width / 2, y, { align: "center" });

              // 5. Signatures (Page 1 Bottom)
              const sigY = height - 50;

              // Director
              docPdf.line(margin + 10, sigY, margin + 70, sigY);
              if(directorSignature) docPdf.addImage(directorSignature, 'PNG', margin + 15, sigY - 20, 50, 18);
              docPdf.setFontSize(10);
              docPdf.text("Diretor Executivo", margin + 40, sigY + 5, { align: "center" });

              // Secretary
              docPdf.line(width - margin - 70, sigY, width - margin - 10, sigY);
              if(secSignature) docPdf.addImage(secSignature, 'PNG', width - margin - 65, sigY - 20, 50, 18);
              docPdf.text("Secretaria Geral", width - margin - 40, sigY + 5, { align: "center" });

              // Instructor (Center - Optional/Generic)
              docPdf.line((width/2) - 30, sigY, (width/2) + 30, sigY);
              docPdf.text("Instrutor Responsável", width/2, sigY + 5, { align: "center" });

          } else {
              // --- SIMPLE DOCUMENT DESIGN (Declaração/Histórico) ---
              // No gold border, simpler layout

              let y = 20;

              if (schoolConfig.logoUrl) {
                  docPdf.addImage(schoolConfig.logoUrl, 'PNG', 20, y, 20, 20);
                  // Text next to logo
                  docPdf.setFont("helvetica", "bold");
                  docPdf.setFontSize(18);
                  docPdf.text(schoolConfig.schoolName || "ESCOLA BÍBLICA EAD", 50, y + 8);
                  docPdf.setFontSize(10);
                  docPdf.setFont("helvetica", "normal");
                  docPdf.text(`CNPJ: ${schoolConfig.cnpj || '---'}`, 50, y + 15);
                  y += 30;
              } else {
                  docPdf.setFont("helvetica", "bold");
                  docPdf.setFontSize(18);
                  docPdf.text(schoolConfig.schoolName || "ESCOLA BÍBLICA EAD", width/2, y, {align:'center'});
                  y += 20;
              }

              docPdf.line(20, y, width - 20, y);
              y += 15;

              docPdf.setFont("helvetica", "bold");
              docPdf.setFontSize(16);
              docPdf.text(docTitle, width / 2, y, { align: "center" });
              y += 20;

              docPdf.setFont("times", "normal");
              docPdf.setFontSize(12);
              const margin = 25;

              // Text Content
              let bodyText = "";
              if (docType === 'matricula') {
                  bodyText = `Declaramos para os devidos fins que o(a) Sr(a). ${opStudent.displayName}, inscrito(a) no CPF ${opStudent.cpf}, encontra-se regularmente MATRICULADO(A) no curso de ${courseData.nome || 'Teologia'}, sob matrícula nº ${opStudent.academicId}. Situação Acadêmica atual: ${opStudent.status?.toUpperCase()}.`;
              } else if (docType === 'historico') {
                  bodyText = `Certificamos que o(a) aluno(a) ${opStudent.displayName}, matrícula ${opStudent.academicId}, obteve o seguinte desempenho acadêmico no curso de ${courseData.nome || '---'}:`;
              } else {
                  bodyText = `Declaramos que o(a) aluno(a) ${opStudent.displayName}, solicitou transferência nesta data.`;
              }

              const splitBody = docPdf.splitTextToSize(bodyText, width - (margin * 2));
              docPdf.text(splitBody, margin, y);
              y += (splitBody.length * 7) + 10;

              if (docType === 'historico') {
                  const tableBody = modulesData.map((m: any) => [
                      m.title || "Módulo", "20h", "10.0", "APROVADO"
                  ]);
                  autoTable(docPdf, {
                      startY: y,
                      head: [['Disciplina', 'C.H.', 'Nota', 'Situação']],
                      body: tableBody,
                      theme: 'grid',
                      margin: { left: margin, right: margin }
                  });
                  y = (docPdf as any).lastAutoTable.finalY + 20;
              }

              // Footer for Simple Docs
              const dateStr = `São Paulo, ${new Date().toLocaleDateString('pt-BR', {day:'numeric', month:'long', year:'numeric'})}.`;
              docPdf.text(dateStr, width - margin, height - 40, { align: "right" });

              // Digital Stamp
              docPdf.setDrawColor(0);
              docPdf.rect(width/2 - 40, height - 35, 80, 15);
              docPdf.setFontSize(8);
              docPdf.text("ASSINADO DIGITALMENTE - SISTEMA EAD", width/2, height - 28, { align: "center" });
              docPdf.text(`Hash: ${code}`, width/2, height - 23, { align: "center" });
          }

          // --- PAGE 2: BACK (Only for Certificate) ---
          if (isCertificate) {
              docPdf.addPage();

              docPdf.setFont("helvetica", "bold");
              docPdf.setFontSize(14);
              docPdf.text("VERSO - HISTÓRICO E DETALHES", width / 2, 20, { align: "center" });

              let y2 = 40;
              docPdf.setFontSize(10);
              docPdf.setFont("helvetica", "normal");
              docPdf.text(`Curso: ${courseData.nome || '---'}`, 20, y2);
              docPdf.text(`Carga Horária Total: ${modulesData.length * 20} horas`, 20, y2 + 6);
              docPdf.text(`Aluno: ${opStudent.displayName}`, 20, y2 + 12);

              y2 += 20;

              // Modules Table
              const tableBody = modulesData.map((m: any) => [
                  m.title || "Módulo",
                  "20h",
                  "10.0", // Simulado
                  "APROVADO"
              ]);

              autoTable(docPdf, {
                  startY: y2,
                  head: [['Disciplina / Módulo', 'C.H.', 'Nota Final', 'Situação']],
                  body: tableBody,
                  theme: 'striped',
                  headStyles: { fillColor: [50, 50, 50] },
                  styles: { fontSize: 9 },
                  margin: { left: 20, right: 20 }
              });

              // Instructors
              let y3 = (docPdf as any).lastAutoTable.finalY + 20;
              docPdf.setFont("helvetica", "bold");
              docPdf.text("Instrutores Responsáveis:", 20, y3);
              y3 += 7;
              docPdf.setFont("helvetica", "normal");
              docPdf.text(`- ${courseData.professorResponsavel || 'Corpo Docente EB-EAD'}`, 25, y3);

              // QR Code for Validation at Bottom of Page 2
              const finalY = height - 50;
              docPdf.line(20, finalY - 10, width - 20, finalY - 10);

              docPdf.text("Verificação de Autenticidade:", 20, finalY);
              docPdf.addImage(qrCodeDataUrl, 'PNG', 20, finalY + 5, 25, 25);
              docPdf.setFontSize(8);
              docPdf.text(`Código: ${code}`, 50, finalY + 15);
              docPdf.text("Acesse o portal para validar a veracidade deste documento.", 50, finalY + 20);
          }

          const pdfBase64 = docPdf.output('datauristring');
          const pdfBlob = docPdf.output('blob');

          // Save to Files
          await addDoc(collection(db, 'secretaria_arquivos'), {
              name: `${docTitle} - ${opStudent.displayName}.pdf`, type: 'file', mimeType: 'application/pdf', url: pdfBase64,
              parentId: 'root', createdAt: serverTimestamp(), createdBy: user.uid, studentId: opStudent.uid, docType: docType,
              docData: { code, title: docTitle, date: new Date().toISOString(), student: { displayName: opStudent.displayName, cpf: opStudent.cpf, academicId: opStudent.academicId }, courseData, modulesData }
          });

          const blobUrl = URL.createObjectURL(pdfBlob); window.open(blobUrl, '_blank');
          alert("Documento gerado com sucesso!");
      } catch (e: any) { console.error("Erro PDF:", e); alert("Erro ao gerar: " + e.message); } finally { setIsGeneratingPdf(false); }
  };

  const handleNavigate = (folder: any) => { setCurrentFolderId(folder.id); setFolderPath([...folderPath, { id: folder.id, name: folder.name }]); };
  const handleBreadcrumb = (index: number) => { const newPath = folderPath.slice(0, index + 1); setFolderPath(newPath); setCurrentFolderId(newPath[newPath.length - 1].id); };
  const saveEditedStudent = async () => { if (!editingStudent) return; try { await updateDoc(doc(db, 'users', editingStudent.uid), { ...editingStudent, updatedAt: serverTimestamp() }); alert('Atualizado.'); setAuditModalOpen(false); setEditingStudent(null); } catch (e: any) { alert('Erro: ' + e.message); } };
  const validateStudent = async () => { if (!editingStudent) return; try { await updateDoc(doc(db, 'users', editingStudent.uid), { status: 'ativo', updatedAt: serverTimestamp() }); alert('Matrícula validada.'); setAuditModalOpen(false); setEditingStudent(null); } catch (e: any) { alert('Erro: ' + e.message); } };

  return (
    <div className="space-y-4 h-full flex flex-col pb-6">
      <header className="flex flex-col md:flex-row justify-between items-center bg-slate-900 p-4 text-white gap-4 rounded-xl shadow-lg print:hidden shrink-0">
        <div className="flex items-center gap-3">
           <div className="p-2 bg-indigo-600 rounded-lg shadow-lg"><Archive size={20}/></div>
           <div><h1 className="text-lg font-black uppercase italic tracking-tighter leading-none">Secretaria Digital</h1><p className="text-[9px] text-indigo-400 font-bold uppercase tracking-widest mt-0.5 italic">Gestão & Atendimento</p></div>
        </div>
        <div className="flex bg-slate-800 p-1 rounded-lg shadow-inner border border-white/5">
           {(['atendimento', 'chat', 'arquivos', 'operacional'] as any).map((t:any) => (
             <button key={t} onClick={() => { setActiveTab(t); setOpSubView('main'); if(t !== 'chat') setActiveTicket(null); }} className={`px-4 py-2 text-[9px] font-black uppercase italic transition-all rounded-lg ${activeTab === t ? 'bg-white text-slate-900' : 'text-slate-400 hover:text-white'}`}>{t}</button>
           ))}
        </div>
      </header>

      <main className="flex-1 overflow-hidden flex flex-col relative">
         {/* TAB: ATENDIMENTO (TICKETS) */}
         {activeTab === 'atendimento' && (
             <div className="flex-1 bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden flex flex-col">
                <div className="p-4 border-b border-slate-100 flex flex-col md:flex-row items-center justify-between bg-slate-50 gap-4">
                    <div className="flex gap-2 overflow-x-auto w-full md:w-auto">
                       {['todos', 'pendente', 'ativo', 'finalizado', 'arquivado'].map((f:any) => (
                           <button key={f} onClick={() => { setTicketFilter(f); setCurrentPage(1); }} className={`px-3 py-1.5 rounded-lg text-[10px] font-black uppercase transition-all whitespace-nowrap ${ticketFilter === f ? 'bg-indigo-600 text-white' : 'bg-white border border-slate-200 text-slate-500 hover:bg-slate-100'}`}>{f}</button>
                       ))}
                    </div>
                    <div className="flex gap-2 w-full md:w-auto">
                        <div className="relative flex-1 md:flex-none">
                            <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400"/>
                            <input value={ticketSearchTerm} onChange={e => setTicketSearchTerm(e.target.value)} placeholder="Buscar protocolo, nome, matrícula..." className="pl-9 pr-4 py-2 rounded-xl border border-slate-200 text-xs font-bold w-full md:w-64 outline-none focus:ring-1 focus:ring-indigo-600" />
                        </div>
                        <button onClick={() => setShowManualTicketModal(true)} className="px-4 py-2 bg-slate-900 text-white rounded-xl text-[10px] font-black uppercase shadow-lg hover:bg-indigo-600 transition-all flex items-center gap-2 whitespace-nowrap"><Plus size={14}/> Novo Manual</button>
                    </div>
                </div>
                <div className="flex-1 overflow-y-auto p-0">
                    <table className="w-full text-left border-collapse">
                        <thead className="bg-slate-50 sticky top-0 z-10 text-[9px] font-black uppercase text-slate-400 border-b border-slate-200 tracking-widest">
                            <tr>
                                <th className="px-6 py-4">Protocolo</th>
                                <th className="px-6 py-4">Aluno / Matrícula</th>
                                <th className="px-6 py-4">Descrição do Problema</th>
                                <th className="px-6 py-4">Tempo Espera</th>
                                <th className="px-6 py-4">Status / Prioridade</th>
                                <th className="px-6 py-4 text-right">Ações de Gestão</th>
                            </tr>
                        </thead>
                        <tbody className="text-xs divide-y divide-slate-50">
                            {paginatedTickets.map(t => (
                                <tr key={t.id} className="hover:bg-slate-50/80 transition-colors group">
                                    <td className="px-6 py-4 font-mono font-bold text-indigo-600">#{t.protocolo}</td>
                                    <td className="px-6 py-4">
                                        <div className="flex flex-col">
                                            <span className="font-bold text-slate-900">{t.user}</span>
                                            <span className="text-[9px] text-slate-400 italic">ID: {t.senderId?.substr(0,8)}</span>
                                        </div>
                                    </td>
                                    <td className="px-6 py-4 max-w-xs truncate text-slate-600 font-medium">{t.lastMessage}</td>
                                    <td className="px-6 py-4 font-mono text-[10px]">{formatTimeWait(t.createdAt?.seconds)}</td>
                                    <td className="px-6 py-4">
                                        <span className={`px-3 py-1 rounded-full text-[8px] font-black uppercase border ${
                                            t.status === 'Pendente' ? 'bg-amber-50 text-amber-600 border-amber-200' :
                                            t.status === 'Resolvido' || t.status === 'Finalizado' ? 'bg-emerald-50 text-emerald-600 border-emerald-200' :
                                            t.status === 'Arquivado' ? 'bg-slate-100 text-slate-500 border-slate-200' :
                                            'bg-indigo-50 text-indigo-600 border-indigo-200'
                                        }`}>{t.status}</span>
                                    </td>
                                    <td className="px-6 py-4 text-right">
                                        <div className="flex justify-end gap-2">
                                            <button onClick={() => setViewTicketModal(t)} className="p-2 bg-white border border-slate-200 text-slate-400 rounded-lg hover:text-indigo-600 hover:border-indigo-200 transition-all" title="Ver Card Completo"><Eye size={14}/></button>
                                            <button onClick={() => { setActiveTicket(t); setActiveTab('chat'); }} className="p-2 bg-indigo-50 text-indigo-600 border border-indigo-100 rounded-lg hover:bg-indigo-600 hover:text-white transition-all" title="Ir para Chat"><ArrowRightLeft size={14}/></button>
                                            {t.status !== 'Arquivado' && <button onClick={() => handleArchiveTicket(t.id)} className="p-2 bg-white border border-slate-200 text-slate-400 rounded-lg hover:text-amber-600 hover:border-amber-200 transition-all" title="Arquivar"><Archive size={14}/></button>}
                                            <button onClick={() => handleDeleteTicket(t.id)} className="p-2 bg-white border border-slate-200 text-slate-400 rounded-lg hover:text-rose-600 hover:border-rose-200 transition-all" title="Excluir"><Trash2 size={14}/></button>
                                        </div>
                                    </td>
                                </tr>
                            ))}
                            {paginatedTickets.length === 0 && <tr><td colSpan={6} className="p-10 text-center text-slate-400 font-medium italic text-xs">Nenhum registro encontrado.</td></tr>}
                        </tbody>
                    </table>
                </div>
                {/* Pagination Controls */}
                <div className="p-4 border-t border-slate-100 bg-slate-50 flex justify-between items-center text-[10px] font-bold uppercase text-slate-500">
                    <div className="flex items-center gap-2">
                        <span>Exibir:</span>
                        <select value={itemsPerPage} onChange={e => setItemsPerPage(Number(e.target.value))} className="bg-white border border-slate-200 rounded p-1">
                            <option value={10}>10</option>
                            <option value={20}>20</option>
                            <option value={50}>50</option>
                        </select>
                        <span>por página</span>
                    </div>
                    <div className="flex items-center gap-2">
                        <button disabled={currentPage === 1} onClick={() => setCurrentPage(p => p - 1)} className="px-3 py-1 bg-white border rounded disabled:opacity-50 hover:bg-slate-100"><ChevronLeft size={12}/></button>
                        <span>Pág {currentPage} de {totalPages || 1}</span>
                        <button disabled={currentPage === totalPages || totalPages === 0} onClick={() => setCurrentPage(p => p + 1)} className="px-3 py-1 bg-white border rounded disabled:opacity-50 hover:bg-slate-100"><ChevronRight size={12}/></button>
                    </div>
                </div>
             </div>
         )}

         {/* TAB: CHAT (Kept same) */}
         {activeTab === 'chat' && (
             <div className="flex-1 bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden flex flex-col relative h-full">
                {activeTicket ? (
                  <>
                    <div className="p-4 border-b border-slate-100 bg-slate-50 flex justify-between items-center shrink-0">
                       <div className="flex items-center gap-4">
                           <button onClick={() => { setActiveTab('atendimento'); setActiveTicket(null); }} className="p-2 hover:bg-slate-200 rounded-lg text-slate-400"><ArrowRightLeft size={16}/></button>
                           <div>
                               <h3 className="font-black text-slate-900 text-sm uppercase italic">Protocolo #{activeTicket.protocolo}</h3>
                               <p className="text-[9px] font-bold text-slate-500 uppercase tracking-widest mt-0.5 flex items-center gap-1"><UserIcon size={10}/> {activeTicket.user} • {activeTicket.status}</p>
                           </div>
                       </div>
                       <div className="flex gap-2">
                           <button onClick={() => setActiveTicket(null)} className="px-4 py-2 bg-slate-100 text-slate-500 rounded-lg text-[9px] font-black uppercase hover:bg-slate-200 transition-all">Fechar Chat</button>
                           {activeTicket.status !== 'Arquivado' && (
                               <button 
                                   onClick={handleDynamicButton}
                                   className={`px-6 py-2 text-white rounded-lg text-[9px] font-black uppercase transition-all shadow-lg flex items-center gap-2 ${
                                       activeTicket.status === 'Pendente' ? 'bg-indigo-600 hover:bg-indigo-700' :
                                       activeTicket.status === 'Em Atendimento' ? 'bg-emerald-600 hover:bg-emerald-700' :
                                       'bg-slate-900 hover:bg-slate-800'
                                   }`}
                               >
                                   {activeTicket.status === 'Pendente' ? 'Assumir Atendimento' : 
                                    activeTicket.status === 'Em Atendimento' ? 'Finalizar Atendimento' : 'Arquivar Protocolo'}
                               </button>
                           )}
                       </div>
                    </div>

                    <div className="flex-1 overflow-y-auto p-6 space-y-4 bg-slate-100 custom-scrollbar">
                       {messages.map((m, i) => (
                         <div key={i} className={`flex ${m.sender === 'Secretaria' || m.sender === 'Sistema' ? 'justify-end' : 'justify-start'}`}>
                            <div className={`max-w-[70%] p-4 rounded-2xl text-xs font-medium leading-relaxed shadow-sm relative ${
                                m.sender === 'Secretaria' ? 'bg-indigo-600 text-white rounded-tr-none' : 
                                m.sender === 'Sistema' ? 'bg-slate-800 text-white rounded-tr-none' : 
                                'bg-white text-slate-800 rounded-tl-none border border-slate-200'
                            }`}>
                               {m.sender === 'Sistema' && <p className="text-[8px] font-black uppercase text-slate-400 mb-1 tracking-widest">Bot Automático</p>}
                               {m.text}
                               {m.attachmentUrl && (
                                   <button onClick={() => viewAttachment(m.attachmentUrl)} className="mt-2 flex items-center gap-2 px-3 py-2 bg-black/10 rounded-lg hover:bg-black/20 transition-all w-full">
                                       <FileText size={14}/> <span className="text-[9px] font-bold uppercase underline">Ver Anexo</span>
                                   </button>
                               )}
                               <span className={`text-[8px] font-bold mt-2 block text-right ${m.sender === 'Aluno' ? 'text-slate-300' : 'text-white/60'}`}>
                                   {m.createdAt?.seconds ? new Date(m.createdAt.seconds * 1000).toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'}) : '...'}
                               </span>
                            </div>
                         </div>
                       ))}
                       <div ref={chatEndRef} />
                    </div>

                    {activeTicket.status !== 'Arquivado' && activeTicket.status !== 'Resolvido' && activeTicket.status !== 'Finalizado' && (
                        <div className="p-4 border-t border-slate-200 bg-white shrink-0">
                            <div className="flex gap-3 items-end">
                                <div className="flex gap-1">
                                    <button onClick={() => chatFileInputRef.current?.click()} className="p-3 bg-slate-100 text-slate-500 rounded-xl hover:bg-indigo-50 hover:text-indigo-600 transition-all" title="Do Computador"><Paperclip size={20}/></button>
                                    <button onClick={() => { setActiveTab('arquivos'); setAttachMode(true); }} className="p-3 bg-slate-100 text-slate-500 rounded-xl hover:bg-indigo-50 hover:text-indigo-600 transition-all" title="Do Sistema"><Folder size={20}/></button>
                                </div>
                                <input type="file" ref={chatFileInputRef} className="hidden" onChange={handleChatFileUpload}/>
                                <div className="flex-1 bg-slate-50 border border-slate-200 rounded-xl flex items-center px-4">
                                    <input 
                                        value={chatMessage} 
                                        onChange={e => setChatMessage(e.target.value)} 
                                        onKeyDown={e => e.key === 'Enter' && sendMessage()} 
                                        className="flex-1 bg-transparent border-none py-3 text-xs font-bold text-slate-800 outline-none placeholder:text-slate-400" 
                                        placeholder="Digite sua resposta..." 
                                    />
                                </div>
                                <button onClick={sendMessage} className="p-3 bg-indigo-600 text-white rounded-xl shadow-lg hover:bg-indigo-700 transition-all active:scale-95"><Send size={20}/></button>
                            </div>
                        </div>
                    )}
                  </>
                ) : (
                  <div className="flex-1 flex flex-col items-center justify-center text-slate-300 gap-6">
                      <div className="w-24 h-24 bg-slate-50 rounded-full flex items-center justify-center animate-pulse"><MessageSquare size={40} className="text-slate-200"/></div>
                      <p className="text-xs font-black uppercase tracking-widest opacity-50">Selecione um ticket na aba "Atendimento"</p>
                  </div>
                )}
             </div>
         )}

         {/* TAB: ARQUIVOS (File explorer code kept same) */}
         {(activeTab === 'arquivos' || attachMode) && !activeTicket && (
           <div className={`bg-white border border-slate-200 rounded-2xl overflow-hidden h-full flex flex-col shadow-sm ${attachMode ? 'fixed inset-10 z-[3000] border-indigo-600 border-4 shadow-2xl' : ''}`}>
              <div className="p-4 bg-slate-50 border-b border-slate-200 flex justify-between items-center">
                 <div className="flex items-center gap-2 overflow-x-auto">
                    <button onClick={() => { setCurrentFolderId('root'); setFolderPath([{id:'root', name:'Arquivos'}])}} className="p-2 hover:bg-slate-200 rounded-lg text-slate-500"><Home size={16}/></button>
                    {folderPath.map((f, i) => (
                      <React.Fragment key={f.id}>
                        {i > 0 && <ChevronRight size={14} className="text-slate-300"/>}
                        <button onClick={() => handleBreadcrumb(i)} className={`text-xs font-bold px-2 py-1 rounded-lg hover:bg-slate-200 ${i === folderPath.length -1 ? 'text-slate-900 bg-white shadow-sm' : 'text-slate-500'}`}>{f.name}</button>
                      </React.Fragment>
                    ))}
                 </div>
                 <div className="flex gap-2">
                    <input type="file" ref={fileInputRef} className="hidden" onChange={handleUploadFile} />
                    <button onClick={() => fileInputRef.current?.click()} className="px-3 py-2 bg-white border border-slate-200 text-slate-700 rounded-lg text-[9px] font-black uppercase flex items-center gap-2 hover:bg-slate-50"><UploadCloud size={14}/> Upload</button>
                    <button onClick={handleCreateFolder} className="px-3 py-2 bg-slate-900 text-white rounded-lg text-[9px] font-black uppercase flex items-center gap-2 hover:bg-indigo-600"><FolderPlus size={14}/> Nova Pasta</button>
                    {attachMode && <button onClick={() => setAttachMode(false)} className="px-3 py-2 bg-rose-600 text-white rounded-lg text-[9px] font-black uppercase">Cancelar Anexo</button>}
                 </div>
              </div>
              <div className="flex-1 overflow-y-auto p-6 custom-scrollbar bg-slate-50/30">
                 {currentItems.length === 0 ? (
                   <div className="h-full flex flex-col items-center justify-center opacity-30 gap-4"><Folder size={64} className="text-slate-300" /><p className="text-xs font-black uppercase tracking-widest text-slate-400">Pasta Vazia</p></div>
                 ) : (
                   <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-6 gap-4">
                      {currentItems.map(item => (
                        <div key={item.id} 
                             onDoubleClick={() => item.type === 'folder' ? handleNavigate(item) : null}
                             className={`bg-white p-4 rounded-xl border border-slate-100 shadow-sm hover:shadow-md transition-all group flex flex-col items-center text-center cursor-pointer relative`}
                        >
                           <div className={`w-14 h-14 rounded-2xl flex items-center justify-center mb-3 text-white shadow-inner ${item.type === 'folder' ? 'bg-amber-400' : 'bg-indigo-500'}`}>
                              {item.type === 'folder' ? <Folder size={28} className="fill-white/50"/> : <FileText size={28} className="fill-white/50"/>}
                           </div>
                           <p className="text-[10px] font-bold text-slate-700 line-clamp-2 leading-tight w-full break-words">{item.name}</p>
                           {item.type === 'file' && !attachMode && (
                             <div className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 flex gap-1 bg-white/90 rounded-lg p-1 shadow-sm transition-opacity">
                               <button onClick={async (e) => { e.stopPropagation(); if(confirm('Apagar?')) await deleteDoc(doc(db, 'secretaria_arquivos', item.id)); }} className="p-1.5 bg-rose-50 text-rose-600 rounded-lg hover:bg-rose-100"><Trash2 size={12}/></button>
                               <button onClick={(e) => { e.stopPropagation(); setFileToMove(item); setMoveModalOpen(true); }} className="p-1.5 bg-slate-50 text-slate-600 rounded-lg hover:bg-slate-100"><Move size={12}/></button>
                               <button onClick={(e) => { e.stopPropagation(); viewFile(item); }} className="p-1.5 bg-indigo-50 text-indigo-600 rounded-lg hover:bg-indigo-100"><Eye size={12}/></button>
                             </div>
                           )}
                        </div>
                      ))}
                   </div>
                 )}
              </div>
           </div>
         )}

         {/* TAB: OPERACIONAL */}
         {activeTab === 'operacional' && (
           <div className="h-full flex flex-col md:flex-row gap-6 overflow-hidden">
              <div className="w-full md:w-64 flex flex-col gap-2 shrink-0 overflow-y-auto">
                 <button onClick={() => setOpSubView('declaracao')} className={`p-4 rounded-xl border flex items-center gap-3 transition-all ${opSubView === 'declaracao' ? 'bg-indigo-600 text-white border-indigo-600 shadow-lg' : 'bg-white border-slate-200 hover:bg-slate-50 text-slate-600'}`}><FileText size={18}/><span className="text-xs font-black uppercase">Declarações</span></button>
                 <button onClick={() => setOpSubView('certificado')} className={`p-4 rounded-xl border flex items-center gap-3 transition-all ${opSubView === 'certificado' ? 'bg-indigo-600 text-white border-indigo-600 shadow-lg' : 'bg-white border-slate-200 hover:bg-slate-50 text-slate-600'}`}><Award size={18}/><span className="text-xs font-black uppercase">Certificados</span></button>
                 <button onClick={() => setOpSubView('historico')} className={`p-4 rounded-xl border flex items-center gap-3 transition-all ${opSubView === 'historico' ? 'bg-indigo-600 text-white border-indigo-600 shadow-lg' : 'bg-white border-slate-200 hover:bg-slate-50 text-slate-600'}`}><Archive size={18}/><span className="text-xs font-black uppercase">Histórico Escolar</span></button>
                 <button onClick={() => setOpSubView('transferencia')} className={`p-4 rounded-xl border flex items-center gap-3 transition-all ${opSubView === 'transferencia' ? 'bg-indigo-600 text-white border-indigo-600 shadow-lg' : 'bg-white border-slate-200 hover:bg-slate-50 text-slate-600'}`}><ArrowRightLeft size={18}/><span className="text-xs font-black uppercase">Transferência</span></button>
                 <button onClick={() => setOpSubView('validacao')} className={`p-4 rounded-xl border flex items-center gap-3 transition-all ${opSubView === 'validacao' ? 'bg-indigo-600 text-white border-indigo-600 shadow-lg' : 'bg-white border-slate-200 hover:bg-slate-50 text-slate-600'}`}><UserCheck size={18}/><span className="text-xs font-black uppercase">Auditoria</span></button>
                 <button onClick={() => setIsSignModalOpen(true)} className="p-4 rounded-xl border bg-white border-slate-200 hover:bg-slate-50 flex items-center gap-3 transition-all text-slate-600 mt-auto"><Fingerprint size={18}/><span className="text-xs font-black uppercase">Minha Assinatura</span></button>
              </div>

              <div className="flex-1 bg-white rounded-2xl border border-slate-200 p-1 shadow-sm overflow-hidden relative">
                 {(opSubView === 'declaracao' || opSubView === 'certificado' || opSubView === 'historico' || opSubView === 'transferencia') && (
                   <div className="max-w-lg mx-auto space-y-6 py-10 px-6 h-full overflow-y-auto">
                      <h3 className="text-xl font-black uppercase italic text-slate-900 border-b pb-4">Gerar Documento Oficial</h3>
                      <div className="space-y-2">
                         <label className="text-[10px] font-black uppercase text-slate-400">Selecione o Aluno</label>
                         <select onChange={e => setOpStudent(students.find(s => s.uid === e.target.value))} className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-xs font-bold outline-none focus:ring-1 focus:ring-indigo-600">
                            <option value="">Selecione...</option>
                            {students.map(s => <option key={s.uid} value={s.uid}>{s.displayName} (RA: {s.academicId})</option>)}
                         </select>
                      </div>

                      <div className="grid grid-cols-2 gap-4">
                          <div className={`p-4 rounded-xl border text-center ${secSignature ? 'bg-emerald-50 border-emerald-200 text-emerald-700' : 'bg-rose-50 border-rose-200 text-rose-700'}`}>
                              <p className="text-[9px] font-black uppercase mb-1">Assinatura Secretário</p>
                              <p className="text-xs font-bold">{secSignature ? "Validada" : "Pendente"}</p>
                          </div>
                          <div className={`p-4 rounded-xl border text-center ${directorSignature ? 'bg-emerald-50 border-emerald-200 text-emerald-700' : 'bg-amber-50 border-amber-200 text-amber-700'}`}>
                              <p className="text-[9px] font-black uppercase mb-1">Assinatura Diretor</p>
                              <p className="text-xs font-bold">{directorSignature ? "Validada" : "Simulada (Pendente)"}</p>
                          </div>
                      </div>

                      <div className="pt-4 flex gap-4">
                         {opSubView === 'declaracao' && (
                           <button disabled={!opStudent || isGeneratingPdf} onClick={() => generateLegalPDF('matricula')} className="w-full py-4 bg-indigo-600 text-white rounded-xl text-[10px] font-black uppercase shadow-lg disabled:opacity-50 hover:bg-indigo-700 transition-all flex items-center justify-center gap-2">
                                {isGeneratingPdf ? <RefreshCw className="animate-spin" size={14}/> : <Printer size={14}/>} Gerar Declaração
                           </button>
                         )}
                         {opSubView === 'certificado' && (
                           <button disabled={!opStudent || isGeneratingPdf} onClick={() => generateLegalPDF('conclusao')} className="w-full py-4 bg-indigo-600 text-white rounded-xl text-[10px] font-black uppercase shadow-lg disabled:opacity-50 hover:bg-indigo-700 transition-all flex items-center justify-center gap-2">
                                {isGeneratingPdf ? <RefreshCw className="animate-spin" size={14}/> : <Award size={14}/>} Emitir Diploma (Premium)
                           </button>
                         )}
